quests[42809] = { id = 42809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion von Niskara", description = "Es ist alles an Ort und Stelle. Alle Systeme sind funktionsfähig und wir haben ausreichend Treibstoff. Der Sprungantrieb der Teufelshammer ist bereit.\n\nCaria und Varedis wissen, dass Ihr zu ihnen unterwegs seid. Belaths Informationen zufolge haben sie sich auf die Dämonengefängniswelt Niskara zurückgezogen.\n\nEs wird Zeit, diese Invasion zu beginnen und dem Ganzen ein für alle Mal ein Ende zu machen.", sourceObjective = "Aktiviert die Steuerkonsole der Teufelshammer und schließt das Szenario \"Die Invasion von Niskara\" ab.", completion = "Wir waren heute siegreich! Caria und Varedis sind tot, und wir haben der Brennenden Legion ein klares Zeichen dafür gesetzt, dass sie auch auf ihren eigenen Welten niemals sicher vor uns ist.\n\nDas gehört gebührend gefeiert, doch erst...", sourceObjectiveStatus = "unverified-source-field" }
quests[42810] = { id = 42810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Angebot", description = "Was war das? Es klingt, als ob etwas da draußen ist.\n\nEtwas Großes...\n\nGeht besser da hoch, {name}!", sourceObjective = "Untersucht, was sich außerhalb der Teufelshammer abspielt.", completion = "Kil'jaeden?! Also wenn das kein hingeworfener Fehdehandschuh ist, dann weiß ich es auch nicht.\n\nKönnen wir das überleben, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[42811] = { id = 42811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Hoffnungsvollen Licht", description = "Wir müssen Hochlord Tirion zur Ruhe betten.\n\nFür einen Paladin seines Kalibers ist nur ein Ort geeignet: das Sanktum des Hoffnungsvollen Lichts, eine geheime Bastion des Lichts, die unter unserer Kapelle verborgen liegt.\n\nPaladine aus aller Welt werden an der Zeremonie teilnehmen. Aber Euer Beisein hätte Tirion mehr bedeutet als das aller anderen.", sourceObjective = "Trefft Euch mit den anderen Paladinen im Sanktum des Hoffnungsvollen Lichts unter der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", completion = "Eure Teilnahme hier ist wahrlich mehr als angemessen.\n\nEin ums andere Mal habt Ihr unsere Welt gerettet. Und jetzt, fürchte ich, muss ich Euch um einen noch größeren Dienst bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42812] = { id = 42812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen am Hoffnungsvollen Licht", description = "{name}, bevor wir zu den Verheerten Inseln ziehen, müssen wir Hochlord Tirion zur Ruhe betten.\n\nFür einen Paladin seines Kalibers ist nur ein Ort geeignet: das Sanktum des Hoffnungsvollen Lichts, eine geheime Bastion des Lichts, die hier unter unserer Kapelle hier verborgen liegt.\n\nPaladine aus aller Welt haben sich bereits unten zu der Zeremonie eingefunden. Sie warten nur noch auf Euch.", sourceObjective = "Trefft Euch mit den anderen Paladinen im Sanktum des Hoffnungsvollen Lichts unter der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[42813] = { id = 42813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran Hidden Demon 02" }
quests[42814] = { id = 42814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wichtige Mission", description = "Champion! Ich habe eine dringende Nachricht von Danath Trollbann.\n\nEr wünscht, dass Ihr ihn bei Krasus' Landeplatz aufsucht. Es geht um eine wichtige Mission, die Euer besonderes Geschick erfordert!", sourceObjective = "Sprecht mit Danath Trollbann bei Krasus' Landeplatz in Dalaran.", completion = "Ich bin froh, dass Ihr die Verheerte Küste überlebt habt, obwohl so viele tapfere Helden dort ihr Leben lassen mussten.\n\n<Danath neigt für einen Moment sein Haupt in Trauer.>\n\nMan hat mich aus der Ehrenfeste abgezogen, damit ich der Allianz in ihrer dunkelsten Stunde zur Seite stehe. Wir müssen unbedingt aus unseren Fehlern lernen.\n\nHabt Ihr einen Moment Zeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[42815] = { id = 42815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Verheerten Küste", description = "Wenn ich in diesem Krieg meinen Beitrag leisten soll, brauche ich Informationen aus erster Hand. Ich werde zur Verheerten Küste fliegen und mir das Schlachtfeld mit eigenen Augen ansehen.\n\nIhr habt Euch als <fähiger Anführer/fähige Anführerin> erwiesen und wart selbst dort. Ich möchte wissen, was Ihr denkt.\n\nWollt Ihr mich zur Verheerten Küste begleiten? Ich glaube nicht, dass wir unterwegs auf Feinde treffen, aber wenn der Teufelssturm im Spiel ist, kann man sich nie sicher sein.", sourceObjective = "Nehmt Danaths Ersatzreittier, begebt Euch zur Verheerten Küste und helft nach besten Kräften aus.", completion = "Willkommen in den Hallen der Tapferkeit. Normalerweise muss man erst sterben, um hier eintreten zu dürfen, aber die Zeiten haben sich geändert.", sourceObjectiveStatus = "unverified-source-field" }
quests[42816] = { id = 42816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'sharah Hidden Demon 03" }
quests[42817] = { id = 42817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'sharah Hidden Demon 02" }
quests[42818] = { id = 42818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Scharlachroten", description = "Die Hochinquisitorin des Scharlachroten Kreuzzugs?!\n\nIhr werdet Hochinquisitorin Weißsträhne nicht zusammen mit den Namen gefallener Helden in den Annalen der Geschichte angeführt sehen.\n\nUnd dennoch... Ungeachtet ihres Wahnsinns und ihres Fanatismus war sie dem Licht stärker verbunden als selbst die größten Paladine.\n\nEs gibt nicht mehr viele Scharlachrote Kreuzfahrer auf dieser Welt, aber das Scharlachrote Kloster ist keineswegs verlassen. Es ist jetzt das Zuhause der fanatischsten und verrücktesten Kreuzfahrer, die dem Orden noch geblieben sind.\n\nNur ein groß angelegter Angriff kann den Erfolg gewährleisten.", sourceObjective = "Sprecht mit Thassarian im Scharlachroten Kloster.", completion = "Gut, dass Ihr hier seid, Todesgebieter {name}. Die Schlacht hat schon begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42819] = { id = 42819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taschenzauberer" }
quests[42820] = { id = 42820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Aegir Wellenschmetterer" }
quests[42821] = { id = 42821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausheben einer Armee", description = "Wir haben unterschätzt, wie viele Scharlachrote Kreuzfahrer sich noch in diesem Kloster befinden. Die Schlacht um die Kathedrale zieht sich zu lange hin.\n\nZeit, ein wenig raffinierter vorzugehen...\n\nErweckt die gefallenen Kreuzfahrer als Ghule wieder und schickt sie gegen ihre Brüder und Schwestern in die Schlacht.\n\nDer Scharlachrote Kreuzzug wird der Flut der Untoten nicht lange standhalten können.", sourceObjective = "Erweckt 12 eitrige Ghule aus den Leichnamen von Scharlachroten Kreuzfahrern.", completion = "Der Scharlachrote Kreuzzug wird bald völlig überrannt sein, Todesgebieter {name}. Diese Schlacht ist in Kürze vorüber...", sourceObjectiveStatus = "unverified-source-field" }
quests[42823] = { id = 42823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Kommandant", description = "Es liegt nur noch eine Hürde zwischen uns und dem Grab von Sally Weißsträhne.\n\nOberkommandant Gutkind bewacht den Weg zum Grab. Er mag ein fanatischer Mörder sein, doch er ist auch ein kampfgestählter Ritter, der sein ganzes Leben damit zugebracht hat, unseresgleichen zu vernichten.\n\nWir dürfen ihn nicht unterschätzen...\n\nTötet ihn, dann ist unsere Aufgabe hier so gut wie erfüllt.", sourceObjective = "Tötet Oberkommandant Gutkind.", progress = "Habt Ihr Oberkommandant Gutkind getötet?", completion = "Unser Weg liegt jetzt ganz klar vor uns, Todesgebieter. Es ist jetzt an der Zeit, Sally Weißsträhne eine Gelegenheit zur Sühne anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42824] = { id = 42824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zelotin erhebt sich", description = "Manchmal liegt der Unterschied zwischen Held und Bösewicht im Auge des Betrachters. Als Hochinquisitorin sah Sally Weißsträhne sich als Champion der Menschen im Krieg gegen die Geißel. Und doch hat der Scharlachrote Kreuzzug unter ihrer Führung neben den Untoten auch Lebende dahingemetzelt.\n\nDer Tod kann einer Seele stillen Frieden bringen, doch nicht Sally Weißsträhne. Ihr Tod ist von Reue und Unruhe geprägt.\n\nWir werden ihr eine Gelegenheit bieten, Abbitte für ihre Verbrechen zu leisten. Der Preis dafür ist hoch, doch ich bezweifle nicht, dass sie ihn zahlen wird.", sourceObjective = "Lasst Sally Weißsträhne als Todesritter wiederauferstehen.", completion = "Ich habe gehört, dass die Schlacht um das Scharlachrote Kloster siegreich war und dass dies Euch zu verdanken ist.\n\nInitiandin Weißsträhne hat bereits ihre Ausbildung als {class} begonnen. Sie zeigt viel Potenzial und wird zweifelsohne eine furchterregende Reiterin abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42825] = { id = 42825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna Hidden Demon 01" }
quests[42826] = { id = 42826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmountain Hidden Demon 01" }
quests[42827] = { id = 42827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mana Chests 01" }
quests[42828] = { id = 42828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Motten in das Licht", description = "Ihr habt sicherlich schon unsere Gäste bemerkt.\n\nIch habe sie eine ganze Weile beobachtet und festgestellt, dass sie von dem Baum angezogen werden. Ich weiß nicht, ob sie unserem Setzling gefährlich werden können, aber wir dürfen kein Risiko eingehen.\n\nSammelt bitte eine Handvoll dieser Insekten ein und bringt sie mir. Ich werde sie dann untersuchen und entscheiden, ob sie harmlos sind oder nicht.", sourceObjective = "Sammelt 4 Tiefenscheinheuschrecken ein.", progress = "Habt Ihr ein brauchbares Exemplar gefunden?", completion = "Hm, ja. Es ist, wie ich vermutet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[42829] = { id = 42829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutritt verschaffen", description = "Ihr müsst für mich die Zwielichtrebgärten infiltrieren und mir etwas mitbringen, das gegen diese Insekten hilft.\n\nHierzu müsst Ihr zunächst an den Wachen vorbei, welche die Gärten vor Eindringlingen schützen.\n\nLy'leth sollte uns dabei helfen können. Ich sage ihr, sie soll sich mit Euch in der Nähe des Eingangs treffen.\n\nUnd nun geht!", sourceObjective = "Trefft Euch mit Ly'leth Lunastre vor den Zwielichtrebgärten.", progress = "Kann ich Euch helfen?", completion = "Gut, ich führe Euch dann mal herum.", sourceObjectiveStatus = "unverified-source-field" }
quests[42830] = { id = 42830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezieferbehandlung" }
quests[42831] = { id = 42831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shal'an" }
quests[42832] = { id = 42832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Früchte unserer Arbeit", description = "Meine Aufgabe hier besteht darin, den Schein zu wahren.\n\n<Margaux lächelt entschuldigend.>\n\nIhr werdet das Gehabe ertragen müssen, während ich Euch durch den Rebgarten führe. Nur so können wir vermeiden, Verdacht zu erregen.\n\nIch werde Euch so gut ich kann helfen, aber nur, wenn es sicher ist.\n\nKommt mit. Die erste Station ist der Verkostungspavillon. Dort könnt Ihr die Früchte unserer Arbeit probieren.", sourceObjective = "Verkostet die Honiggesüßte Infusion, den samtigen Nektar und das cremige Gebräu.", progress = "Findet Ihr Gefallen daran?", completion = "Vielleicht benötigt Ihr zwischen den Proben etwas, um Euren Gaumen zu neutralisieren. Wir bieten hier ein paar starke Aromen an!", sourceObjectiveStatus = "unverified-source-field" }
quests[42833] = { id = 42833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So wird's gemacht: Arkwein", description = "<Margaux spricht mit gedämpfter Stimme.>\n\nWährend wir durch den Rebgarten wandern, können wir ja ein paar Informationen austauschen.\n\nLasst Euch nicht anmerken, falls Euch das, was Ihr hier erblickt, beunruhigen sollte.\n\n<Margaux erzwingt ein kurzes und abwesendes Lächeln.>\n\nSollen wir weiter?", sourceObjective = "Folgt Margaux durch den Rebgarten. Tauscht dort, wo es möglich ist, Informationen aus.", completion = "Willkommen! Genießt Ihr die Besichtigung?", sourceObjectiveStatus = "unverified-source-field" }
quests[42834] = { id = 42834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höchste Konzentration", description = "Ich hoffe, Ihr wisst, dass dies eine seltene Ehre ist. Es wird nicht jedem gestattet, sich an diesem geweihten Ort aufzuhalten.\n\n<Sylverin richtet würdevoll seine Manschetten aus.>\n\nUm an der Vorführung teilzunehmen, nehmt Ihr Euch einfach ein Energiegefäß und begebt Euch zu uns in den Teich.\n\nFangt dann mit der Schüssel die kleinen Tautröpfchen der Nachtbrunnenenergie auf. Nur so lässt sich die Essenz auf sichere Weise handhaben.\n\nWenn Euer Behältnis voll ist, begebt Ihr Euch zu unserem Vorführungsfass und gießt die Infusion vorsichtig dort hinein.\n\nViel Vergnügen!", sourceObjective = "Fangt 15 Tropfen Nachtbrunnenessenz mithilfe eines Energiegefäßes auf.", progress = "Gibt es Probleme?", completion = "Einfach, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[42835] = { id = 42835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf altmodische Weise", description = "Während Ihr das überwältigende Erlebnis der Nachtbrunneninfusion genossen habt, hat Margaux bereits eine weitere Vorführung für Euch vorbereitet.\n\nGeht über die Brücke und dann nach links, dann über eine weitere Brücke und dann nach rechts. Ihr findet sie dort auf der Entsaftungsveranda.\n\nWeiterhin viel Vergnügen bei Eurer Besichtigung!\n\n<Sylverin lässt ein extrem gekünsteltes Grinsen aufblitzen.>", sourceObjective = "Nehmt an einer Entsaftungsvorführung teil.", completion = "Ich werde Sorge tragen, dass eine Flasche Eures Arkweins für Euch bereitsteht, bevor Ihr geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42836] = { id = 42836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidenflügelsabotage", description = "Motten. Diese Tiere sind ja so... barbarisch!\n\nSie fressen unsere Ernte auf und die Manawyrms tun nichts, um sie davon abzuhalten.\n\nIhr. Ihr seht doch ganz fähig aus. Unternehmt etwas gegen diese Kreaturen, damit wir unsere Ernte rechtzeitig einfahren können.\n\nAlso... bitte.", sourceObjective = "Tötet 8 ramponierte Seidenflügel.", completion = "Viel besser. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42837] = { id = 42837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleichgewicht im Überfluss", description = "Dies ist der letzte Teil unserer Besichtigung. Ihr könnt jetzt frei und nach Belieben durch den Garten wandeln.\n\nDort werdet Ihr eine große Anzahl in der Luft schwebender Manawyrms bemerken.\n\nIch bin mir sicher, dass der Rebgarten ein paar von ihnen nicht missen würde.\n\nViel Glück bei Eurem Insektenproblem, <mein Freund/meine Liebe>.\n\n<Margaux schenkt Euch ein warmes Lächeln.>", sourceObjective = "Sammelt 8 Fliegenfresser der Schattenschuppen ein.", completion = "Ich werde diese... ähem... Andenken... für Euch einpacken lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42838] = { id = 42838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Wendepunkt", description = "<Sylverin betrachtet Euch besorgt.>\n\nIch sollte mich hier mit Euch und Margaux treffen und Euch aus dem Rebgarten geleiten.\n\nMeine Herrin Margaux ist stets pünktlich. Ich fürchte, etwas Furchtbares ist geschehen.\n\nBitte sucht sie und stellt sicher, dass es ihr gut geht.", sourceObjective = "Sucht nach Margaux.", progress = "Wie war Euer Ausflug in den Rebgarten?", completion = "Margaux... Nein!", sourceObjectiveStatus = "unverified-source-field" }
quests[42839] = { id = 42839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtiger Kontakt", description = "Das ist einfach nur... unaussprechlich.\n\nMargaux hat alles aufs Spiel gesetzt, um uns diese Manawyrms zu verschaffen. Ich kann nicht zulassen, dass es so endet.\n\nIhr müsst jemanden finden, der sich der Sache annimmt. Jemanden, der nicht aufgibt, bevor Aufseher Durant tot ist.\n\nSprecht mit Vanthir. Ich bin sicher, er wird wissen, wen wir brauchen.", sourceObjective = "Sprecht mit Vanthir.", completion = "Verzweifelt nicht, {name}.\n\nDer Verlust von Margaux ist bedauerlich, wird aber wohl nicht der letzte bleiben. Ganz im Gegenteil, fürchte ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[42840] = { id = 42840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Worte nicht ausreichen", description = "Sofern Ihr nicht einen guten Grund wisst, aus dem ich mein Leben riskieren sollte, rühre ich keinen Finger.\n\nVanthir hat Euch wahrscheinlich schon davon unterrichtet, dass meine Dienste nicht eben günstig sind.\n\nWie wäre es mit... so viel Mana, dass es einen Monat für mich reicht?\n\n<Arluin schaut Euch selbstgefällig an, als würdet Ihr niemals auf solch eine absurde Forderung eingehen.>", sourceObjective = "Bestecht Arluin mit 800 uraltem Mana.", progress = "Der Preis ist nicht verhandelbar. Wie steht's mit unserer Abmachung?", completion = "Freut mich, dass Ihr den Wert meiner Dienste zu schätzen wisst.", sourceObjectiveStatus = "unverified-source-field" }
quests[42841] = { id = 42841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fette Beute", description = "Ich bin nicht sonderlich reich, aber ich habe einige Informationen, die für Leute mit Euren Fähigkeiten von Vorteil sein können. Ihr habt mir geholfen und jetzt könnt Ihr Euch selbst helfen.\n\nDie Magistrix erhält jeden Tag eine Lieferung Arkwein, die von einer schwer bewaffneten Eskorte zum Palast gebracht wird. Wenn Ihr die Beute mit mir teilt, würde ich Euch die Route verraten.\n\nEiner meiner Männer hat die Gruppe infiltriert und wird die Lieferung lange genug aufhalten, damit Ihr zuschlagen könnt.", sourceObjective = "Greift die Arkweinlieferung der Magistrix an und bringt Arluin seinen Anteil der Beute.", progress = "Wo ist mein Anteil?", completion = "Es ist eine Freude, Geschäfte mit Euch zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42842] = { id = 42842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mana Cap 01 Kel'danath's Flask" }
quests[42844] = { id = 42844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsende Macht", description = "Lord Maxwell Tyrosus wünscht, Euch im Sanktum des Lichts zu sehen.\n\nUnsere Kampagne zur Verteidigung der Verheerten Inseln ist angelaufen und wir brauchen Euch am Ruder.", sourceObjective = "Sprecht mit Maxwell Tyrosus im Sanktum des Lichts.", completion = "Danke, dass Ihr so schnell gekommen seid, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[42846] = { id = 42846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutmatriarchin", description = "Mir werden noch viele folgen. Ihr müsst aber den Heiligsten aller Paladine finden, damit er unserem Orden als Champion dient.\n\nMir fällt nur noch ein Paladin ein, dem diese Ehre gebührt: Lady Liadrin, die Matriarchin der Blutritter.\n\nGeht und sprecht mit ihr.", sourceObjective = "Gewinnt Lady Liadrin als Champion des Ordens der Silbernen Hand.", completion = "Hervorragend. Sowohl Lord Tyrosus als auch Lady Liadrin werden mit Stolz dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42847] = { id = 42847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Stürme", description = "Seid gegrüßt, Hochlord.\n\nNeben mir seht Ihr die Späherkarte. Über sie könnt Ihr unseren Verbündeten wichtige Missionen überall auf den Verheerten Inseln auftragen.\n\nDer erste Auftrag ist absolut entscheidend. Die Stürme über dem Grabmal des Sargeras werden schlimmer. Wir sollten unsere Champions entsenden, damit sie die Region im Auge behalten und nach möglichen Überlebenden suchen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Dunkle Stürme\" ab.", completion = "Maxwell Tyrosus ist mit wichtigen Neuigkeiten zurückgekehrt. Erstens: Er hat einige Überlebende gefunden. Sie erholen sich gerade in der Kapelle. Unter ihnen war auch Kommandantin Ansela. Sie ist nicht nur ein erfahrener {class}, sondern auch eine große Lehrmeisterin.\n\nZweitens: Das soll Lord Tyrosus Euch selbst erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42848] = { id = 42848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Kommandantin Ansela ist eine erfahrene Kriegsheldin und Lehrerin. Sie hat viele unserer tapfersten Ritter ausgebildet.\n\nSprecht mit ihr und rekrutiert einen Trupp Knappen.", sourceObjective = "Sprecht mit Kommandantin Ansela und rekrutiert einen Trupp Knappen.", progress = "Zusätzliche Truppen werden uns bei den kommenden Missionen gute Dienste leisten.", completion = "Gut. Diese Knappen werden uns im Kampf eine große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42849] = { id = 42849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn und Gerechtigkeit", description = "Eine neue Mission erfordert Eure Aufmerksamkeit, Hochlord {name}. Herdweiler wurde von einer kleinen Dämonenarmee angegriffen.\n\nSie wollen zweifellos unsere Stärke und Entschlossenheit auf die Probe stellen.\n\nAn Stärke mangelt es uns gewiss nicht, aber meine Geduld geht langsam zur Neige. Wir sollten unsere Champions und Trupps entsenden, um diese Bedrohung zu vernichten.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Zorn und Gerechtigkeit\" ab.", progress = "Wir werden dem Feind zeigen, mit wem er es zu tun hat.", completion = "Unsere Mission war ein voller Erfolg! Wir konnten nicht nur den Feind besiegen, sondern auch Alamande Graudorn anwerben, einen berühmten Gelehrten aus den Archiven von Herdweiler.", sourceObjectiveStatus = "unverified-source-field" }
quests[42850] = { id = 42850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Alamande Graudorn ist unter den Gelehrten des Lichts wohlbekannt.\n\nDem Schlachtfeld hat er schon lange den Rücken gekehrt, aber sein Geist ist scharf wie eh und je. Es würde mich auch nicht überraschen, wenn er noch heute das eine oder andere Duell für sich entscheiden könnte.\n\nSprecht mit ihm. Vielleicht weiß er, wie man die Hallen unseres Ordens aufwerten könnte.", sourceObjective = "Sprecht mit Alamande Graudorn und wählt eine Aufwertung der Klassenordenshalle aus.", completion = "Hervorragend. Ich wusste, auf Sir Graudorn ist Verlass.", sourceObjectiveStatus = "unverified-source-field" }
quests[42851] = { id = 42851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Verteidiger Boros", sourceObjective = "Hochlord, ich kann Euch nicht genug dafür danken, dass Ihr mir das Leben gerettet und die Augen geöffnet habt.\n\nZwar verspüre ich enormen Hass auf die Brennende Legion, doch Ihr habt mich daran erinnert, dass ich meinen Weg mit meinen Entscheidungen festlege.\n\nIch habe mich für den rechtschaffenen Weg entschieden und werde Eurer leitenden Hand folgen, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[42852] = { id = 42852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Justiziarin Julia Celeste", sourceObjective = "Ich höre schon seit Jahren von Euren Taten, Hochlord. Nun, da ich an Eurer Seite gekämpft habe, weiß ich, dass die Geschichten auch wahr sind.\n\nErlaubt es mir, den Orden der Silbernen Hand als Champion des Lichts zu vertreten, {name}. Ich werde gerecht und mutig kämpfen und Eure Befehle stets bis ins Letzte erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42857] = { id = 42857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuchtes Fresschen", description = "Es scheint, als würden die Grell sich von diesen Früchten ernähren.\n\nDer alte Graurücken wäre sicher erfreut, wenn sie aus dem Dorf entfernt werden würden.", sourceObjective = "Sammelt 5 feuchte Graukämme in Grauholz.", progress = "Habt Ihr ein paar Früchte gefunden, die mich interessieren könnten?", completion = "Oh ja, dies ist die Nahrung der Grell. Vielleicht kann ich sie nutzen, um sie fortzulocken. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42858] = { id = 42858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormheim Hidden Demon 01" }
quests[42859] = { id = 42859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Trank der Hoffnung" }
quests[42860] = { id = 42860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking - God-King Scene" }
quests[42861] = { id = 42861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Felssturz der Zerfressene" }
quests[42862] = { id = 42862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmountain Hidden Demon 02" }
quests[42863] = { id = 42863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmoutain Hidden Demon 03" }
quests[42864] = { id = 42864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Kapitän Dargun" }
quests[42865] = { id = 42865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greller Wahnsinn", description = "Der Anführer der Grell muss aus dem Weg geräumt werden.\n\nIhr könnt ihn an seiner weißen Haut und seiner scharfen Zunge erkennen.", sourceObjective = "Besiegt Enderkin in Grauholz.", completion = "Ich weiß ja nicht, ob die Grell Mütter haben, aber ich hoffe doch sehr, dass er seine Mutter nie mit diesem Schandmaul geküsst hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[42866] = { id = 42866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen des Himmels", description = "Seid gegrüßt, Hochlord. Ich habe dringende Nachrichten für Euch.\n\nWährend meiner Expedition zur Verheerten Küste habe ich mit eigenen Augen ein auffällig leuchtendes Objekt aus dem Teufelssturm auftauchen sehen. Es raste auf die Küste von Suramar zu und schlug eine Schneise durch den Sturm selbst!\n\nIch fühlte eine unglaubliche Welle der Macht, bevor es hinter dem Horizont verschwand.\n\nWir sollten unverzüglich Erzmagier Khadgar davon erzählen.", sourceObjective = "Sprecht mit Erzmagier Khadgar in Dalaran.", completion = "Ich sehe, dass Ihr eine dringende Nachricht für mich habt. Was gibt es denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[42867] = { id = 42867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen der Silbernen Hand", description = "Das Herz des Lichts wird innerhalb der Mauern unseres Ordens sicher sein, aber es steht für schlechte Neuigkeiten.\n\nWir sollten einen Rat mit den Anführern unseres Ordens einberufen.\n\nGeht und sprecht mit Lady Liadrin, Verteidiger Boros, Justiziarin Julia Celeste, Arator dem Erlöser und Aponi Lichtmähne. In den kommenden Tagen wird ihre Weisheit gefragt sein.", sourceObjective = "Sprecht mit Lady Liadrin, Verteidiger Boros, Justiziarin Julia Celeste, Arator dem Erlöser und Aponi Lichtmähne.", completion = "Danke, dass Ihr alle zusammengebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42868] = { id = 42868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung des Affenkönigs", description = "Ihr könnt flink ausweichen, hart zuschlagen und selbst Feuer lässt Euch nicht verzagen...\nDoch seid Ihr auch folgsam, wenn ich spreche die Worte? Ein Gebräu ist, was ich suche, eins von feinster Sorte!\nMischen Ihr müsst, was Ihr habt gefunden,\nund an jeden meiner Schritte Ihr dabei seid gebunden.\nDie hohe Braukunst wird Euer letzter Test,\nmeistert ihn, und fügen wird sich der Rest.", sourceObjective = "Helft dem Affenkönig, sein Gebräu zu vervollständigen.", progress = "Ah! Dieses Gebräu ist wirklich hervorragend! Absolut eines Königs wert!", completion = "Ein Spitzengebräu das ist, kein Besseres es je gab!\n\nWahrhaft würdig Ihr seid. Euch gebührt mein Stab.", sourceObjectiveStatus = "unverified-source-field" }
quests[42869] = { id = 42869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Wacht", description = "<Als Kor'vas Eure Gleven sieht, bekommt sie ganz große Augen.>\n\nIch bin so gespannt, was diese Prachtstücke alles können! Wie wäre es mit einem kleinen Übungskampf vor der nächsten Jagd?\n\nWährend Eurer Abwesenheit haben wir ein Lager nicht fern von diesem Landeplatz errichtet, damit wir die Legion im Auge behalten können. Wir sollten sofort dorthin aufbrechen. Jace braucht Eure Hilfe. Es klang ziemlich wichtig!", sourceObjective = "Gleitet zur Wehr der Illidari bei Krasus' Landeplatz.", completion = "Ich habe unglaubliche Neuigkeiten für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42870] = { id = 42870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Kathaw der Wilde" }
quests[42871] = { id = 42871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tome of Illusions - Azeroth" }
quests[42872] = { id = 42872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg sichern", description = "Ich konnte Kontakt zu unseren Truppen in Mardum aufnehmen. Sie haben nach unserer Abreise vor all den Jahren die Teufelshammer gesichert und seitdem halten können!\n\nMalicia hat das Warpsystem des Schiffes dazu verwendet, den Großteil unserer Truppen an Bord zu bringen, aber dadurch wurde der letzte kleine Energievorrat in großem Maße belastet.\n\nIch glaube, dass es einen besseren Weg gibt.\n\nEure Gleven enthalten einen Teil der Energie von Kil'jaeden. Mit ihrer Hilfe sollte es Euch möglich sein, ein permanentes Portal zur Teufelshammer zu öffnen.", sourceObjective = "Verwendet Eure Gleven, um ein Loch in die Realität zu reißen und ein Portal zur Teufelshammer in Mardum zu öffnen.", progress = "Bald werden unsere Kräfte ungehindert zwischen diesem Ort und der Teufelshammer wechseln.", completion = "Ich freue mich schon darauf, endlich zum Rest unserer Streitmacht aufzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
