quests[42880] = { id = 42880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erfüllte Soll" }
quests[42881] = { id = 42881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lady Liadrin", sourceObjective = "Seid gegrüßt, {name}. Man sagte mir, dass Ihr der Schreckensherrschaft der Dämonen ein Ende setzen wollt. Ist das wahr?\n\nDie Legion hat unser Volk über zahlreiche Welten gejagt und dabei unzählige Leben genommen... Mit jedem {class}, der fällt, windet sich auch das Licht vor Schmerzen.\n\nGenug ist genug. Ich werde an Eurer Seite kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42882] = { id = 42882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Massaker des Scharlachroten Kreuzzugs", description = "Wir haben hier nur eine Aufgabe: Sally Weißsträhne als Todesritter der Schwarzen Klinge auferstehen zu lassen. Das ist unser Ziel, und wir werden es erledigen.\n\nDer Scharlachrote Kreuzzug hat die Bewohner Azeroths jedoch lange genug in Angst und Schrecken versetzt. Deshalb ist unsere Arbeit hier am heutigen Tag nicht getan, bis jeder einzelne Kreuzfahrer gefallen, jeder Stein zertrümmert und jedes Banner verbrannt ist.\n\nKommt, <Todesgebieter/Todesgebieterin>. Lasst uns dem Scharlachroten Kreuzzug seinen Untergang bereiten.", sourceObjective = "Tötet 16 Scharlachrote Kreuzfahrer.", progress = "Der Scharlachrote Kreuzzug wird brennen.", completion = "Der Scharlachrote Kreuzzug wird für seine Verbrechen bezahlen. Das Kloster wird schon bald fallen und die letzte Überlebenshoffnung des Kreuzzugs mit ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[42883] = { id = 42883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grell sind los", description = "Die Grell sind rasend. Sie greifen meine Brüder an und zerstören unser Dorf!\n\nBitte, <Fremder/Fremde>, helft uns, diese niederträchtigen Übeltäter unter die Erde zu befördern.", sourceObjective = "Tötet 8 irre Untergrell in Grauholz.", completion = "Ich danke Euch, {name}. In unserem Dorf seid Ihr jederzeit willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42884] = { id = 42884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwurzelung", description = "Als ich zu Hause ankam, war die Eingangstür durch magische Wurzeln versperrt.\n\nIch konnte sie entfernen, doch nur wenige Anhänger meines Stammes verfügen über die Fähigkeiten, es mir gleichzutun.\n\nNehmt meinen Stab. Seine Macht sollte die störenden Wurzeln mit Leichtigkeit entwirren.", sourceObjective = "Nutzt den Stab des alten Graurückens, um 5 verworrene Dornengestrüppe in Grauholz zu vernichten.", completion = "Die Grell haben unsere Jungen in den Hütten eingesperrt. Doch dank Eurer großzügigen Bemühungen sind sie nicht mehr in Gefahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[42885] = { id = 42885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Hochlords", description = "Schreckenslord Balnazzar zu finden, hat jetzt oberste Priorität für uns. Wir sollten Verteidiger unseres Ordens ausschicken, um seine Spur aufzunehmen.", sourceObjective = "Schließt die Mission \"Der Befehl des Hochlords: Nemesis\" ab.", completion = "Gut. Diese Geheiminformationen werden uns bei unseren Operationen sehr dienlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42886] = { id = 42886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Faronaar", description = "Wir behalten das Treiben der Legion bei Faronaar in Azsuna im Auge.\n\nUnseren Informationen zufolge plant ein hochrangiger Befehlshaber, womöglich sogar Schreckenslord Balnazzar persönlich, die Angriffe in der Region.\n\nDas könnte unsere Gelegenheit sein, der Führungsriege der Legion einen empfindlichen Schlag zu versetzen.\n\nVerteidiger Boros befehligt unsere Streitkräfte an der Front. Er wäre für Eure Unterstützung dankbar, Hochlord.", sourceObjective = "Sprecht mit Verteidiger Boros am Alten Küstenpfad.", completion = "Ausgezeichnet, Hochlord. Ihr seid hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[42887] = { id = 42887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So sieht Vergeltung aus", description = "Die Wut schwelt in mir wie eine heiße Glut.\n\nWenn sie nur ein wenig angefacht wird, bricht eine lodernde Flamme hervor.\n\nDer Angriff der Legion auf die Exodar hat genau das bewirkt, Hochlord. Noch einmal sehe ich nicht zu, wie meine Brüder und Schwestern sterben.\n\nAb jetzt bin ich es, der tötet. Ich werde für Gerechtigkeit sorgen! Helft mir, Hochlord, und vernichtet alle Dämonen, denen ihr in den unteren Regionen von Faronaar begegnet.", sourceObjective = "Tötet 20 Dämonen in den unteren Regionen von Faronaar.", completion = "Prächtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[42888] = { id = 42888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationskugeln", description = "Wir haben wichtige Aufgaben zu erledigen, Hochlord.\n\nIm gesamten Lager der Legion sind Kugeln verteilt, die für ihre Planung und Strategien unverzichtbar sind.\n\nWenn wir die zerstören, wäre das ein massiver Rückschlag für sie. Ich werde Euch begleiten, Hochlord, um es mit Euch gemeinsam zu Ende zu bringen.", sourceObjective = "Zerstört 3 Kugeln der Legion.", completion = "Nein... Wir haben den Feind unterschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42889] = { id = 42889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg nach Hause", description = "Hallo? Hier spricht Großtelemant Oculeth. Wie ich sehe, seid Ihr sicher hinausgekommen!\n\nIch stelle gerade Euren Standort ein. Ihr müsst von Eurer Seite aus den Signalgeber aktivieren, damit wir eine Teleportationsverbindung herstellen können.\n\nVerstanden? Gut.", sourceObjective = "Aktiviert den Signalgeber.", completion = "Als wir Euch plötzlich nicht mehr wahrnehmen konnten, haben wir schon das Schlimmste befürchtet.\n\nIch kann mir keinen Reim auf Eure Abenteuer machen... Ich werde eine Weile brauchen, um diese Tragödie aufzuarbeiten.\n\nAber ich freue mich natürlich, dass Ihr unversehrt zurückgekehrt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[42890] = { id = 42890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex der Befehlsgewalt", description = "Boros ist in großer Gefahr.\n\nDer Teufelslord Jarvox bewacht die Grube im Westen. Auch Boros ist darin gefangen.\n\nWir müssen Jarvox bezwingen, ihm seinen Kodex der Befehlsgewalt abnehmen und Verteidiger Boros retten.\n\nIch stehe an Eurer Seite, Hochlord!", sourceObjective = "Besorgt Euch 1 Kodex der Befehlsgewalt und rettet Verteidiger Boros.", progress = "Hochlord, Ihr seid zurückgekehrt.", completion = "Unsere Mission in Faronaar war ein Erfolg... trotz meiner Torheit.\n\nMein Zorn hat mich übermannt, und ohne Euch hätte ich das wohl teuer bezahlt.\n\nVielen Dank, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
