quests[42909] = { id = 42909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Mark of the Bleeding Hollow" }
quests[42910] = { id = 42910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Mark of Blackrock" }
quests[42911] = { id = 42911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkenes Mana", description = "Was hat Euch eigentlich hierher verschlagen? Aber egal, das ist jetzt ganz und gar unwichtig. Wichtig ist nur, dass Ihr mir helft!\n\nIch sehe, dass Ihr Erfahrung im Angeln habt. Würdet Ihr vielleicht Eure Talente in meine Dienste stellen?", sourceObjective = "Angelt versunkenes Mana für Beschwörer Margoss.", progress = "Na, beißen sie?", completion = "Ja, das ist es! Damit kann ich etwas anfangen. Bitte bringt mir so viel davon, wie Ihr könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[42912] = { id = 42912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Legion - Dungeon Normal - 1st" }
quests[42913] = { id = 42913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Legion - Dungeon Normal - Nth" }
quests[42914] = { id = 42914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Meryl Teufelssturm", sourceObjective = "Ich kämpfe schon eine Ewigkeit gegen die Brennende Legion, {name}. Es wäre mir eine Ehre, Euch mit meiner Weisheit zur Seite zu stehen, wenn Ihr eine neue Streitmacht gegen sie anführt. Ich glaube, ich habe ein paar Kniffe gelernt, mit denen sie nicht rechnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[42915] = { id = 42915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, spezieller heroischer Dungeon (Erster) (Legion)" }
quests[42916] = { id = 42916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, spezieller heroischer Dungeon (xter) (Legion)" }
quests[42917] = { id = 42917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Erzmagier Vargoth", sourceObjective = "Ihr habt meinen Ruf gerettet, von meinem Leben ganz zu schweigen! Ohne Eure Beharrlichkeit würde ich immer noch über dem Nexus hängen, {name}. Ich hoffe, Ihr akzeptiert meinen ewigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[42918] = { id = 42918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Runen", description = "Hodir hat sich tapfer in das dämonische Portal gestürzt. Er hätte einen ehrenvollen Tod verdient, aber stattdessen hat ihn der Legionsabschaum gefangen genommen.\n\nWir hatten stets vermutet, dass die Schlachten der letzten Tage hier auf Azeroth stattfinden würden, aber wir werden den Feind auf eigenem Boden angreifen, wenn wir damit einen der Unseren vor einem furchtbaren Schicksal bewahren.\n\nHymdall glaubt, dass er mit der richtigen Energiequelle die Tore der Legion neu ausrichten kann. Sammelt dämonische Runensteine von der Legion, auf dass die letzte Schlacht beginnen möge!", sourceObjective = "Besorgt Euch 30 dämonische Runen von Dämonen auf den Verheerten Inseln.", progress = "Habt Ihr die dämonischen Runensteine, {name}?", completion = "Hervorragend! Die Legion wird noch den Tag verfluchen, an dem sie sich mit Azeroth angelegt hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[42919] = { id = 42919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schweres Vermächtnis", description = "Die Anführer der Silbernen Hand sind zusammengekommen. Hört Euch ihren Rat an.", sourceObjective = "Hört dem Rat der Anführer zu.", progress = "Unsere nächsten Schritte sind sehr wichtig.", completion = "Unsere Mission ist eindeutig, aber wie sehen unsere nächsten Schritte aus?", sourceObjectiveStatus = "unverified-source-field" }
quests[42920] = { id = 42920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion von Niskara", description = "Es ist alles an Ort und Stelle. Alle Systeme sind funktionsfähig und wir haben ausreichend Treibstoff. Der Sprungantrieb der Teufelshammer ist bereit.\n\nCaria und Varedis wissen, dass Ihr zu ihnen unterwegs seid. Belaths Informationen zufolge haben sie sich auf die Dämonengefängniswelt Niskara zurückgezogen.\n\nEs wird Zeit, diese Invasion zu beginnen und dem Ganzen ein für alle Mal ein Ende zu machen.", sourceObjective = "Aktiviert die Steuerkonsole der Teufelshammer und schließt das Szenario \"Die Invasion von Niskara\" ab.", completion = "Wir waren heute siegreich! Caria und Varedis sind tot, und wir haben der Brennenden Legion ein klares Zeichen dafür gesetzt, dass sie auch auf ihren eigenen Welten niemals sicher vor uns ist.\n\nDas gehört gebührend gefeiert, doch erst...", sourceObjectiveStatus = "unverified-source-field" }
quests[42921] = { id = 42921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konfrontation am Schwarzen Tempel", description = "Lan'dalocks Buch ist sehr aufschlussreich. Es beschreibt eine Technik, mit deren Hilfe man leicht und elegant die heilige Barriere des Schwarzen Tempels umgehen kann.\n\nIch brauche einen Moment, um ein Tor zu beschwören. Bleibt bitte zurück.", sourceObjective = "Benutzt das Tor zum Schwarzen Tempel und konfrontiert Akama.", completion = "Wer hätte geglaubt, dass er mit uns gemeinsame Sache machen würde?\n\nJetzt sind wir unserem Ziel einen Schritt näher gekommen, den Kampf gegen die Brennende Legion in ihre eigenen Welten zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42922] = { id = 42922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Startsequenz" }
quests[42924] = { id = 42924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Eine finstere Angelegenheit" }
quests[42926] = { id = 42926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Wie ist er da hochgekommen?" }
quests[42927] = { id = 42927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Malisandra" }
quests[42928] = { id = 42928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidengewebte Verbände", progress = "Habt Ihr uns Vorräte mitgebracht?", completion = "Habt Dank, {name}.\n\nMit diesen Verbänden können wir uns um unsere verletzten Verbündeten kümmern." }
quests[42929] = { id = 42929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochberglachs", progress = "Habt Ihr uns Vorräte mitgebracht?", completion = "Ich danke Euch, {name}.\n\nMit diesem Lachs können wir unseren Stamm bei Kräften halten." }
quests[42930] = { id = 42930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Wildrippchen", progress = "Habt Ihr uns Vorräte mitgebracht?", completion = "Habt Dank, {name}.\n\nDieses Fleisch wird unsere Truppen stärken." }
quests[42931] = { id = 42931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo der Hammer fällt", description = "Ihr habt uns alle gerettet, <Schamane/Schamanin>! Vielen Dank!\n\nThrall will sich kopfüber in den Mahlstrom stürzen und den Schicksalshammer bergen, aber ich mache mir große Sorgen um ihn. In der letzten Schlacht wurde er schwer verwundet, und dieser Dämon Geth'xun ist vielleicht noch am Leben. Wir sollten ihn begleiten.\n\nSchwingt Euch auf Sturmschnabel, sobald Ihr bereit seid, und dann suchen wir nach diesem Artefakt!", sourceObjective = "Fliegt auf Sturmschnabel mit Thrall und Mylra in den Mahlstrom.", progress = "Los! Auf in den Mahlstrom!", completion = "Der Schicksalshammer könnte hier überall sein. Und dieser Dämon lebt noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42932] = { id = 42932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Steinmutter", description = "Wir müssen uns aufteilen. Ich bin immer noch ziemlich angeschlagen von meinem Zusammenstoß mit Geth'xun und will nicht, dass die Steinmutter mich für schwach hält. Ihr müsst diese Aufgabe übernehmen.\n\nBegebt Euch zu Therazanes Thron und sprecht mit Therazane selbst. Vielleicht hat sie den Schicksalshammer gesehen.\n\nHelft ihr, wenn sie Euch darum bittet. Sie ist gefährlich und launenhaft, aber das hier ist ihr Reich und ohne ihre Hilfe finden wir hier gar nichts.", sourceObjective = "Begebt Euch zu Therazanes Thron und sprecht mit Therazane der Steinmutter.", completion = "Ihr da! Was ist das für ein Unsinn, der in mein Reich fällt? Grünes Feuer regnet aus dem Mahlstrom herab! Steckt etwa Ihr von der Oberfläche dahinter?\n\n<Ihr erzählt der Steinmutter die ganze Geschichte.>\n\nEin verschwundenes Artefakt, wie? Ich habe es nicht gesehen, weiß aber, wo Ihr mit der Suche beginnen solltet. Erst helft Ihr der Steinmutter und dann hilft sie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42933] = { id = 42933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Teufel mit den Troggs", description = "\"Dämonen\", sagt Ihr? Eine \"Brennende Legion\"? Hmpf! Hier brennt einzig und allein mein Zorn, <Schamane/Schamanin>! Und wenn diese Monster meinen, sie könnten einfach durch mein Reich trampeln, werde ich sie wie Ungeziefer unter meinen zarten Füßchen zerquetschen!\n\nIch habe den Hammer, von dem Ihr sprecht, nicht gesehen, aber die Steintroggs sehen alles, was vom Himmel fällt. Und seit das grüne Feuer direkt an ihrer Heimstatt gelandet ist, laufen sie im Bleichen Hort Amok.\n\nSeid doch so lieb und kümmert Euch um die Teufelsfelstroggs westlich von hier. Vielleicht bringt Ihr ja einen von ihnen zum Sprechen.", sourceObjective = "Tötet 25 Teufelsfelstroggs im Bleichen Hort.", completion = "Troggs. Die sind wirklich lästig. Nichts als Schotter im Kopf. Und sie lassen sich von jedem Kult, Dämon oder Drachen an der Nase herumführen, der sich mir in den Weg stellen will. Vielen Dank, dass Ihr ihnen einen Dämpfer verpasst habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42934] = { id = 42934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Nightmare" }
quests[42935] = { id = 42935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Steindrachen", description = "Als dieser Dämon in mein Reich gefallen ist, muss er etwas mit den Troggs angestellt haben. Noch nie zuvor waren sie für meine geliebten Steindrachen eine Bedrohung.\n\nJetzt wimmelt der Bleiche Hort nur so von ihnen und sie überwältigen die Drachen am Boden. Ihr müsst diesem Frevel Einhalt gebieten und die Drachen befreien! Sie könnten uns später noch gute Dienste leisten.", sourceObjective = "Rettet 6 Steindrachen im Bleichen Hort, indem Ihr die Troggs besiegt, die sie peinigen.", completion = "Sehr, sehr gut, {class}. Endlich schallen ihre entzückenden Rufe wieder durch die ganze Höhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[42936] = { id = 42936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geliebtes Gelege", description = "Ich gebe es ja zu: Die Brutmutter der Steindrachen und ich hatten in der Vergangenheit unsere Differenzen. Sie hat nämlich während des Kataklysmus Todesschwinge unterstützt. Aber Aeosera wurde in ihre Schranken verwiesen, und es ist meine Pflicht, sie zu beschützen.\n\nDas Problem ist nur, dass sie ihre Eier nicht im Stich lassen will, selbst inmitten eines Angriffs der Troggs.\n\nIhr seid doch <ein Schamane/eine Schamanin>! Benutzt Euren natürlichen Magnetismus, um die gefallenen opalschimmernden Wächter im Bleichen Hort wieder zusammenzusetzen. Eskortiert sie zu Aeosera, damit sie ihre Eier sicher in meine Obhut tragen können.", sourceObjective = "Eskortiert 5 opalschimmernde Wächter zu Aeosera.", completion = "Wie köstlich! Aeosera ist wirklich zufrieden mit Euch, {class}. Genau wie ich.\n\nNun denn, es wird Zeit, dass wir Euer Artefakt finden. Dank Eurer Mühen werden uns die Steindrachen jetzt helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42937] = { id = 42937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlägerei am Nadelfels", description = "Die Troggs haben gesehen, wo der Hammer aufgeschlagen ist. Ich wette, die Feiglinge haben der Legion erzählt, wo er ist. Hmpf!\n\nSeit dem Kataklysmus führt ein gewisser \"Borlock\" die Steintroggs an. Endlich bekommt dieser sture Gierhals, was er verdient. Sucht ihn an der Nadelfelsspitze und prügelt die Informationen aus ihm heraus.\n\nNehmt Aeosera mit. Sie und ihre Brut haben auch noch eine Rechnung mit diesen bösartigen kleinen Biestern zu begleichen.", sourceObjective = "Fliegt mit Aeosera zur Nadelfelsspitze und besiegt Borlock aus den Tiefen.", progress = "Ich liebe es, Aeosera in Aktion zu erleben.", completion = "Oh ho ho ho! Ich konnte die Höhle bis hierher beben hören, {name}! Gut, dass endlich mal jemand auf den Stein haut und allen zeigt, wer hier das Sagen hat.\n\nAber nun zu Eurem Hammer. Eure Begleiter haben nichts erreicht, aber ich glaube, Ihr wisst, wohin Euch der Weg als Nächstes führt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[42938] = { id = 42938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Chronos" }
quests[42939] = { id = 42939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Ulthalesh", description = "Das Logbuch enthält die neuesten Informationen über Ulthalesh. Anscheinend wurde es von einem sehr nervösen, aufgeregten oder übergeschnappten Wichtel verfasst und ist kaum lesbar. Bringt es Calydus, damit er es übersetzen kann.", sourceObjective = "Bringt das Logbuch zu Calydus in der Schreckensnarbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[42940] = { id = 42940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ein Wille ist, ist auch ein Weg", description = "Das Oculus scheint der Brennenden Legion anheimgefallen zu sein und ist mit starken Schilden geschützt. Wir müssen einen Weg finden, wie Ihr hineingelangen könnt.\n\nIch vermute, dass Eure Champions uns hier gut helfen können.", sourceObjective = "Bittet Eure Champions, einen Weg in das Oculus zu finden.", completion = "Eure Champions haben gute Arbeit geleistet. Ich denke, jetzt schaffe ich es, Euch in das Oculus zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42941] = { id = 42941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Earthliving" }
quests[42942] = { id = 42942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Flametongue" }
quests[42943] = { id = 42943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Frostbrand" }
