quests[42951] = { id = 42951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Glory of the Clans" }
quests[42952] = { id = 42952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Schädel", description = "Das Logbuch enthält die neuesten Informationen über den Schädel der Man'ari. Anscheinend wurde es von einem sehr nervösen, aufgeregten oder übergeschnappten Wichtel verfasst und ist kaum lesbar. Bringt es Calydus, damit er es übersetzen kann.", sourceObjective = "Bringt das Logbuch zu Calydus in der Schreckensnarbe.", sourceObjectiveStatus = "unverified-source-field" }
quests[42953] = { id = 42953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Seelenbinderin Halldora" }
quests[42954] = { id = 42954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Gefallen", description = "Meryls Krankheit ist besorgniserregend. Ich habe so etwas Ähnliches schon einmal gesehen, doch der Name will mir nicht einfallen...\n\nSprecht mit meiner Freundin. Ich nenne sie Ari. Sie lebt hier in der Halle des Wächters, seit sie zum letzten Mal in Verwendung war. Falls es hier einen Folianten über magische Krankheiten gibt, dann weiß sie, wo wir suchen müssen.", sourceObjective = "Sprecht mit Ari.", completion = "Bücher über magische Krankheiten? Ich weiß, wo es so etwas vielleicht geben könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[42955] = { id = 42955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles nach der richtigen Methode", description = "Erzmagier Khadgar ist ein Freund von mir. Dass er Euch vertraut, ist für mich viel wert.\n\nIch kenne das Buch, das Ihr sucht. Es will jedoch nicht gefunden werden. Es ist alt und wütend und dürstet nach Macht. Wir werden es mit der richtigen Methode überzeugen müssen, aus seinem Versteck zu kommen. Womöglich besänftigt Ihr es, wenn Ihr ihm Nachtbrunnenenergie der Nachtgeborenen in Suramar als Geschenk bringt.", sourceObjective = "Entzieht den Nachtgeborenen in Suramar 50 Phiolen Nachtbrunnenenergie.", progress = "Habt Ihr schon genug Nachtbrunnenenergie gefunden?", completion = "Macht in ihrer reinsten Form. Eine wunderschöne Farbe, nicht wahr? Ein passendes Geschenk für ein Buch der Heilung. Kommst du jetzt heraus, wo du nicht mehr verloren und vergessen bist?", sourceObjectiveStatus = "unverified-source-field" }
quests[42956] = { id = 42956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aris Päckchen", description = "Seht! Es war gleich hier, direkt vor unserer Nase. \"Der Arkanistenleitfaden für seltene Krankheiten\". Schüchternes Ding. Die meisten Bücher möchten nur ab und zu entstaubt und gelesen werden. Wir lassen die Phiolen mit Nachtbrunnenenergie hier, und es wird ganz brav mit Euch mitkommen.\n\nHier. Ich habe das Buch so für Euch verpackt, dass Ihr es Khadgar bringen könnt. Ich habe es in Mottenflügel gewickelt, damit es ruhig und guter Dinge bleibt. Außerdem ist ein Geschenk für Euch mit drin. Nur eine Kleinigkeit.", sourceObjective = "Bringt Erzmagier KhadgarAris Päckchen.\n\nBereitgestellter Gegenstand:", completion = "Ari hat genau das Buch gefunden, das ich brauchte! Und sie hat einen Ring für Euch mit hineingetan.", sourceObjectiveStatus = "unverified-source-field" }
quests[42957] = { id = 42957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in den Osten", description = "Meine Rätsel habt Ihr gelöst, doch Eure Aufgabe ist noch nicht vollbracht.\n\nIch und Eure Antworten erwarten Euch im Tempel der Jadeschlange. Wer hätte das gedacht?", sourceObjective = "Trefft Euch mit dem Affenkönig im Tempel der Jadeschlange im Jadewald.\n\nBereitgestellter Gegenstand:", completion = "Ah, da ist ja der Nappel. Dann zeigt mal, wie es um Eure Braukunst steht!", sourceObjectiveStatus = "unverified-source-field" }
quests[42958] = { id = 42958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 042 - Felblaze Ingress - Small" }
quests[42959] = { id = 42959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller guten Dinge sind drei", description = "Ari ist viel mehr, als der Schein vermuten lässt, wisst Ihr. Sie gehörte einst zu den mächtigsten Erzmagiern auf Azeroth und war Teil des Rats von Tirisfal. Leider hat ihr Geist stark gelitten und sie hat die Halle des Wächters seither nicht mehr verlassen.\n\nSie muss sehr angetan sein von Euch, wenn sie Euch etwas schenkt. Wenn Ihr im Gegenzug etwas Besonderes für sie zurückbringt, denke ich, dass sie Euch überraschen wird. Für sie sind aller guten Dinge drei.", sourceObjective = "Bringt Ari 3 besondere Geschenke. Mächtige Gegner in Dungeons tragen diese bei sich.", progress = "Habt Ihr schon etwas Besonderes für Ari gefunden?", completion = "Wie wunderbar! Ich kann die natürlich nicht einfach behalten. Aber... hört ihr die Bienen im Honigbräu summen? So ein süßer Gesang... ach! Was für eine fabelhafte Idee! Danke, meine kleinen Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[42960] = { id = 42960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy B" }
quests[42961] = { id = 42961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy D" }
quests[42962] = { id = 42962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Korrespondenz", sourceObjective = "Besorgt mithilfe der Zauberklinge der Nachtgeborenen 3 Stapel Briefe von Kurieren der Nachtgeborenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42963] = { id = 42963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Rulf Knochenknacker" }
quests[42964] = { id = 42964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Lagertha" }
quests[42966] = { id = 42966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Hochlords", description = "Eine gute Entscheidung, Hochlord. Wir sollten unsere Rekrutierung weiter forcieren und so unsere Streitkräfte verstärken. Lasst uns unsere Champions aussenden, damit sie sich um diese Aufgabe kümmern.", sourceObjective = "Schließt die Mission \"Der Befehl des Hochlords: Heilige Verbündete\" ab.", completion = "Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[42967] = { id = 42967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Hochlords", description = "Ein wahres Wort, Hochlord. Die Legion ist nicht einfach nur ein Feind, sondern eine riesige Bestie mit vielen Häuptern.\n\nUm diese Bedrohung abzuwenden, müssen wir an allen Fronten stets wachsam bleiben.\n\nWir sollten unsere Champions aussenden, um jeden Angriff der Legion sofort abzuschmettern.", sourceObjective = "Schließt die Mission \"Der Befehl des Hochlords: Widerstand gegen die Legion\" ab.", completion = "Gut gemacht. Das sollte die Legion für eine Weile aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42968] = { id = 42968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Hochlords", description = "Ihr habt recht, Hochlord. Ohne verlässlichen Nachschub sind unsere militärischen Bemühungen sicher nicht von Erfolg gekrönt.\n\nWir brauchen also regelmäßig Waffen, Nahrung, Heilmittel und andere Vorräte.\n\nWir sollten unsere Champions aussenden, um eine Versorgungslinie einzurichten.", sourceObjective = "Schließt die Mission \"Der Befehl des Hochlords: Vorratsbeschaffung\" ab.", completion = "Ausgezeichnet. Unsere Paladine werden gut auf die Schlacht vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42969] = { id = 42969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spion unter uns" }
quests[42970] = { id = 42970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Diamantenkönig", description = "Mein Bruder Magni, der frühere König von Eisenschmiede, ist bei einem Titanenritual in eine Diamantstatue verwandelt worden. Er stand jahrelang versteinert in den Tiefen der Stadt.\n\nAber ich habe gerade erfahren, dass er wieder herumläuft und sagt, er wüsste, wie man die Legion besiegen könnte!\n\nPasst auf, {name}. Ich weiß nicht, ob Magni verrückt ist oder ob er das überhaupt selbst ist. Aber vielleicht kann er uns ja wirklich helfen...\n\nMan sagte, er hätte von Ulduar gesprochen. Ich mache mich jetzt auf den Weg dorthin. Ich wüsste es zu schätzen, wenn Ihr und Khadgar mich begleiten könntet.", sourceObjective = "Begleitet Brann und Khadgar nach Ulduar und hört Euch an, was Magni Bronzebart zu sagen hat.", completion = "Magnis Informationen waren entscheidend für unseren Kampf gegen die Legion. Und es war schön, ihn wiederzusehen.\n\nDoch jetzt müssen wir diesen Folianten über die Säulen der Schöpfung finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[42971] = { id = 42971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle der Elemente", description = "Kommt näher, {race}.\n\nRagnaros in den Feuerlanden, Al'Akir auf seinem Thron der Vier Winde und Neptulon auf seinem Thron der Gezeiten. Seit dem Anbeginn der Welt schon waren sie mir ein Dorn im Auge.\n\nWenn Ihr mir beweist, dass ihr den niederen Elementaren überlegen seid, werde ich Euch lehren, wie Ihr Eure Stärke der ganzen Welt demonstrieren könnt.", sourceObjective = "Besorgt Überreste von Feuer, Wasser und Luft und verdient Euch bei Therazane den Status respektvoll.", progress = "Beweist Eure Meisterschaft der Magie und der Elemente, {race}.", completion = "Jetzt werden Euch die anderen Elemente wahrlich fürchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42972] = { id = 42972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Poisoned" }
quests[42973] = { id = 42973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Rune of Razorice" }
quests[42974] = { id = 42974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal Hodirs", description = "Die Zeit ist gekommen, {name}. Begebt Euch nach Azsuna, reist durch das eingenommene Tor nach Niskara und sucht nach Hodir.\n\nDie Legion wird es noch bereuen, jemals in Azeroth eingefallen zu sein!", sourceObjective = "Trefft Euch mit unseren Truppen am Teufelsfeuervorstoß und schließt das Szenario \"Das Schicksal Hodirs\" ab.", completion = "Ich danke Euch, {name}. Ohne Euch wäre einer der mächtigsten Wächter von Azeroth der Legion in die Hände gefallen.\n\nIhr habt Euch als fähiger Anführer meiner Armeen erwiesen und sogar die Legion auf eigenem Gebiet geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42975] = { id = 42975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Chain Armor" }
quests[42976] = { id = 42976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Ch 3 Tracking Quest" }
quests[42977] = { id = 42977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener des Windsuchers", description = "Die Elementarlords müssen geeint werden, aber seit dem Tod von Al'Akir hat es keinen Windlord mehr gegeben, um die Luftelementare anzuführen.\n\nEinmal gab es einen Erben des Throns der Vier Winde namens Prinz Donneraan, aber der Prinz wurde im Reich der Sterblichen besiegt und wartet immer noch auf seine Wiedergeburt. Es gibt nur einen Mann, der über das Wissen verfügt, wie man die Wiedergeburt des Prinzen erreichen kann.\n\nEs gibt einen Diener Donneraans, der durch den Sand von Silithus streift. Findet ihn und er wird Euch den Weg zeigen.", sourceObjective = "Sprecht mit Hochlord Demitrian in Silithus.", completion = "Was will der Irdene Ring von einem alten Diener des Windsuchers?", sourceObjectiveStatus = "unverified-source-field" }
quests[42978] = { id = 42978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Audienz", description = "{name},\n\nmein Vater führte ein kriegerisches Leben, genau wie Ihr. Er hat mich gelehrt, dass wir für unser Königreich kämpfen müssen, wenn wir ihm wirklich Frieden schenken wollen, und auch Ihr habt gekämpft.\n\nEuer Mut war wirklich beispiellos. Ein solches Maß an Ehre sucht in den Rängen der Allianz seinesgleichen und Euer Heldenmut soll entsprechend gewürdigt werden.\n\nKommt deshalb bitte alsbald zu mir auf die Burg Sturmwind, damit ich Euch angemessen für Eure Dienste entlohnen kann.\n\n- König Anduin Wrynn", sourceObjective = "Meldet Euch bei König Anduin Wrynn auf Burg Sturmwind.", completion = "Es ist mir eine Ehre, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42980] = { id = 42980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Lumenstone 2" }
quests[42982] = { id = 42982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Sieges", description = "Nur ein wahrer Held riskiert jeden Tag das eigene Leben zur Verteidigung seiner Heimat, damit anderen dieses Los erspart bleibt.\n\nIhr habt die Mitglieder und Interessen der Allianz treu, mit unglaublichem Mut und voller Hingabe beschützt.\n\nErlaubt uns daher, Euch zu ehren. Wendet Euch bitte den Helden zu, die sich hier versammelt haben, und reckt Eure Waffe gen Himmel. Ihr sollt die Anerkennung erhalten, die Euch gebührt.", sourceObjective = "Erhebt Eure Waffe und empfangt die Euch gebührende Anerkennung auf Burg Sturmwind.", completion = "Wohlverdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42983] = { id = 42983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistralessenz", description = "Wenn wir die Mahlstromsäule wiederherstellen wollen, müssen wir sie mit der Essenz der Luft erfüllen.\n\nDafür wird eine große Menge Mistralessenz benötigt.\n\nMistralessenz findet Ihr bei vielen Elementaren des Vortexgipfels vor.\n\nWenn Ihr mit einem Vorrat an dieser Elementaressenz zu mir zurückkehrt, kann ich mit der Wiederherstellung der Mahlstromsäule fortfahren.", sourceObjective = "Sammelt 100 Mistralessenzen von Windelementaren im Vortexgipfel. Verwendet das Portal im Herzen von Azeroth, um zum Vortexgipfel zu reisen.", progress = "Habt Ihr die nötige Menge zusammenbekommen?", completion = "Ausgezeichnet. Ihr habt genau die richtige Menge Mistralessenz mitgebracht, um die Säule wiederherstellen zu können!", sourceObjectiveStatus = "unverified-source-field" }
quests[42984] = { id = 42984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Das Szepter der Stürme", description = "Es kann schwierig sein, das Element Luft zu beherrschen. Wir werden einen Weg finden müssen, um es auf magische Weise an der Säule zu verankern.\n\nLuft, ganz gleich wie unbeständig sie ist, kann einem guten Sturm nicht widerstehen.\n\nIm Auge Azsharas besitzt die Nagazauberin Lady Hassnatter ein mächtiges Relikt, das als Szepter der Stürme bekannt ist.\n\nHolt das Szepter und wir werden damit das Element der Luft an die Mahlstromsäule binden.", sourceObjective = "Beschafft das Szepter der Stürme von Lady Hassnatter im Dungeon 'Das Auge Azsharas'.", progress = "Ich hoffe, Ihr konntet Lady Hassnatter problemlos davon überzeugen, sich von dem Szepter zu trennen.", completion = "Ja, das ist es! Damit werde ich das Element Luft gut binden können. Und vielleicht kann ich bei zukünftigen Feierlichkeiten noch ein paar beeindruckende Tricks damit vorführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42985] = { id = 42985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Audienz", description = "{name},\n\nwer nicht auf der Seite der Horde steht, stellt sich gegen sie. Als Champion habt Ihr solche Feinde zuhauf vernichtet.\n\nIch bewundere Eure Hingabe. Dank Euch werden wir zu ungeahnter Macht aufsteigen und die Allianz endgültig in die Schranken weisen.\n\nKommt so schnell wie möglich zu mir nach Unterstadt. Eure Siege verdienen eine angemessene Belohnung.\n\n- Kriegshäuptling Sylvanas Windläufer", sourceObjective = "Meldet Euch bei Kriegshäuptling Sylvanas Windläufer in Unterstadt.", completion = "Das Vergnügen ist ganz meinerseits, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42986] = { id = 42986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde aus Luft", description = "Windlord Donneraan hat den Vortexgipfel zurückerobert, aber nicht alle seiner Untergebenen sind ihrem neuen Anführer wohlgesonnen.\n\nIn seinem Königreich gibt es immer noch Unruhen und scheinbar sind es vier Wesire, die sich gegen ihn auflehnen: Neblon, Zeph, Alacris und Tulmos.\n\nSoll sich Donneraan auf den Krieg gegen die Brennende Legion konzentrieren – wir schicken unsere Champions dem Himmelswall gegen dessen Feinde zu Hilfe.", sourceObjective = "Schließt 4 Missionen \"Donneraans Feinde\" ab.", completion = "Ausgezeichnete Arbeit, Scharfseher. Da sich die Lage in diesem Reich beruhigt hat, kann Windlord Donneraan seine Bemühungen jetzt auf den Krieg konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42987] = { id = 42987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Sieges", description = "Solange Ihr an vorderster Front für uns kämpft, werden wir niemals untergehen. Zusammen werden wir alle vernichten, die sich uns in den Weg stellen.\n\nIhr habt große Opfer zum Wohl der Horde gebracht, und ich sorge dafür, dass Eure Hingabe nicht unbemerkt bleibt.\n\nTretet vor Eure Waffenbrüder und -schwestern, {name}. Tretet vor sie und empfangt die Euch gebührende Anerkennung.", sourceObjective = "Erhebt Eure Waffe und empfangt die Euch gebührende Anerkennung in Unterstadt.", completion = "Ich bin beeindruckt, {name}. Das war eine beachtliche Leistung.\n\nMacht weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[42988] = { id = 42988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenheiler", description = "Die Elemente haben sich versammelt und obwohl die Feuerlande sich erst noch mit uns verbünden müssen, haben wir schon mehr Stärke auf unsere Seite ziehen können als je zuvor.\n\nDa der Krieg mit der Brennenden Legion aber immer noch tobt, müssen wir unseren Blick zuerst auf die Verheerten Inseln richten.\n\nWenn wir uns ausreichend um die direkten Bedrohungen des Kriegs gekümmert haben, werden wir unsere Aufmerksamkeit den Feuerlanden widmen und sie für unsere Sache vereinen.", sourceObjective = "Schließt 10 Weltquests ab.", progress = "Wie ist die Lage?", completion = "Beeindruckend, wirklich beeindruckend, Scharfseher! Alles, was ich glaubte, über Eure Fähigkeiten zu wissen, hat sich als richtig erwiesen.\n\nIhr habt mir geholfen, den von unseren Feinden auf den Verheerten Inseln verursachten Riss zu schließen. In dem Wissen, dass wir das vollbracht haben, können wir nun besser schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42989] = { id = 42989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ma'haat der Unbeugsame", description = "Um die Mahlstromsäule mit der Essenz der Erde zu erfüllen, benötigen wir eins der seltensten Fossile Azeroths: ein Ei.\n\nDas Ei von Gaiath ist kein gewöhnliches Ei. Es enthält die Überreste eines ungeborenen irdenen Urwesens, das perfekt versteinert erhalten wurde. Womöglich könnte man es wiederbeleben, aber davon später mehr.\n\nZunächst müssen wir das Ei finden!\n\nDer Irdene Ring hat Kenntnis von einem uralten Wesen, das ein solches Ei besitzt, doch es will mit Blut bezahlt werden.", sourceObjective = "Sprecht mit Ma'haat dem Unbeugsamen in Tiefenheim, um ein fossiles Ei zu erhalten. Er wird Blut von Sargeras im Gegenzug verlangen.", completion = "<Ma'haat der Unbeugsame spricht mit tiefer, grollender Stimme.>\n\nWas... erbittet Ihr... von der Erde?", sourceObjectiveStatus = "unverified-source-field" }
quests[42990] = { id = 42990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Das irdene Amulett", description = "Allein die Tatsache, dass Ihr das Ei von Gaiath in die Hände bekommen habt, ist eine unglaublich großartige Leistung, doch der nächste Schritt könnte womöglich undurchführbar sein. Dennoch... er ist unsere einzige Hoffnung.\n\nDamit das Ritual erfolgreich ist, müssen wir die in diesem Ei ruhende latente elementare Energie erwecken.\n\nEs gibt einen Gegenstand, der genau das möglicherweise erreichen könnte – ein Relikt, das als irdenes Amulett bekannt ist. Gerüchte besagen, es wurde von Loken höchstpersönlich erschaffen.\n\nEs ging vor langen Jahren verloren und fiel Dargrul dem Unterkönig in die Hände.", sourceObjective = "Holt das irdene Amulett von Dargrul dem Unterkönig in Neltharions Hort zurück.", progress = "Neltharion hat viele wertvolle Relikte gesammelt. Das irdene Amulett war eins davon.", completion = "Ja, das ist genau das, was wir brauchen! Ich kann mich umgehend an die Arbeit machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42991] = { id = 42991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Runenseher Sigvid" }
quests[42992] = { id = 42992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Chain Armor" }
quests[42993] = { id = 42993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Ringmail Armor" }
quests[42994] = { id = 42994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Ringmail Armor" }
quests[42995] = { id = 42995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Gelüste", progress = "Ein solches Ei ist ziemlich wertvoll, Fleischling. Doch mein Hunger bohrt und nagt an mir...\n\nEin derartiger Tausch wird... sehr teuer für Euch.\n\nBringt mir 5 Proben des Bluts von Sargeras, dann gebe ich Euch das Ei.", completion = "<Ma'haat der Unbeugsame schluckt gierig das Blut von Sargeras herunter, während er spricht.>\n\nJa... dasch ischt... genau rischtisch. Dasch Ei gehört Eusch." }
quests[42996] = { id = 42996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mahlstromsäule: Luft", description = "Elementaristin Janai hat vorhin nach Euch gesucht, <Scharfseher/Scharfseherin>. Offenbar waren ihre Studien der Mahlstromsäule äußerst aufschlussreich.\n\nFalls Ihr etwas Zeit erübrigen könnt, solltet Ihr sie aufsuchen, um ihre Fortschritte zu besprechen.", sourceObjective = "Sprecht mit Elementaristin Janai im Herz von Azeroth.", completion = "Schön, Euch zu sehen, Scharfseher. Wir haben viel zu besprechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42997] = { id = 42997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mahlstromsäule: Erde", description = "Elementaristin Janai hat hart daran gearbeitet, die Mahlstromsäule wiederherzustellen. In letzter Zeit hat sie ihre Forschungen auf das Element Erde konzentriert.\n\nIhr solltet mit ihr sprechen, wenn es Euch möglich ist. Ich höre, dass sie kurz vor dem Durchbruch steht.", sourceObjective = "Sprecht mit Elementaristin Janai im Herz von Azeroth.", completion = "Ah, gerade zur rechten Zeit, Scharfseher! Ich hatte gehofft, dass Ihr vorbeischaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[42998] = { id = 42998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Return to Firelands 2 Mission Completed" }
