quests[43001] = { id = 43001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Return to Firelands 5 Mission Completed" }
quests[43002] = { id = 43002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnete Klinge des Windsuchers", description = "Der Irdene Ring möchte also meinen Meister wiederbeleben?\n\n<Hochlord Demitrian lacht, als ob er den Verstand verloren hätte.>\n\nIch wusste, dass dieser Tag kommen wird! Endlich hat die Menschheit die Bedeutung des Windsuchers begriffen!\n\nNach der Ermordung Prinz Donneraans durch verräterische Sterbliche wurde seine Seele in der heiligen Klinge Donnerzorn gefangen.\n\nUm meinen Meister wieder auferstehen zu lassen, müsst Ihr sein Schwert finden und es zum Himmelswall zurückbringen. Nach meinem letzten Wissensstand ist der Verräter, der das Schwert meines Meisters gestohlen hat, zu den Verheerten Inseln gereist, um dort Dämonen zu bekämpfen.", sourceObjective = "Findet die verlorene Klinge des Windsuchers.", progress = "Habt Ihr den Schlüssel gefunden, um Donneraan wiederzuerwecken?", completion = "Diese Klinge könnte tatsächlich der Schlüssel zur Wiederbelebung des Windsuchers sein. Doch sie wurde beschädigt und die Elementarseele darin hat an Kraft verloren.\n\nEs ist gut möglich, dass es bald zu spät sein wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[43003] = { id = 43003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Janai", description = "<Ma'haat der Unbeugsame spricht mit tiefer, grollender Stimme zu Euch.>\n\nHier... ist das Ei von Gaiath. Es gehört nun Euch.\n\nGeht... in Frieden.", sourceObjective = "Kehrt zu Elementaristin Janai im Herz von Azeroth zurück.\n\nBereitgestellter Gegenstand:", completion = "Es ist wahr! Das Ei von Gaiath existiert... und ich sehe es mit eigenen Augen!", sourceObjectiveStatus = "unverified-source-field" }
quests[43004] = { id = 43004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Dreadplate Armor" }
