quests[43012] = { id = 43012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Combatant's Leather Armor" }
quests[43013] = { id = 43013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schule der Schurkenschaft", description = "Hervorragend! Sie scheint sich schon eingelebt zu haben. Das ist auch gut so, denn wir haben bereits jetzt Bedarf an Frischfleisch.\n\nGeht doch mal zu ihr rüber und schaut nach, ob da nicht irgendwelche Diebe auf der faulen Haut herumliegen.", sourceObjective = "Sprecht mit Lonika Stillstreich und bildet eine Banditenbande aus.", completion = "Ich hab den Haufen gesehen. Nicht gerade ein schöner Anblick, aber sie werden sich schon noch nützlich machen.\n\nWie auch immer, sie werden da draußen ja von Vanessa und Garona beaufsichtigt, was könnte da also schiefgehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[43014] = { id = 43014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große böse Wolf", description = "Ihr habt doch sicherlich schon von Winstone Wolf gehört, oder? Natürlich habt Ihr das. Wer hat das nicht?\n\nWährend Ihr also mit der Direktorin geplaudert habt, hatte Lord Rabenholdt die Güte, mich aufzusuchen. Höchstpersönlich. Ich hätte nie damit gerechnet, dass er mal aus dieser Kammer herauskommt.\n\nAuf jeden Fall hat er mit aller Deutlichkeit vorgeschlagen, wie es so seine Art ist, dass wir Garona, Vanessa und unsere neue, fröhliche Banditenbande auf einen Besuch zum Wolf am Rabenholdtanwesen entsenden sollten.\n\nAber sorgt dafür, dass sie sich zivilisiert benehmen, sonst werden wir sie nie wiedersehen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Der große böse Wolf\" ab.", completion = "Puh!\n\n<Nikki reibt sich erleichtert über die Stirn.>\n\nWas immer wir ihm angeboten haben... Ich bin froh, dass er zufrieden damit war. Wenn es anders gekommen wäre, hätte ich mich nämlich blitzartig aus dem Staub gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[43015] = { id = 43015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winstones Vorschläge", description = "Wenn hier jemand für Verbesserungen sorgen kann, dann Winstone Wolf. Der Mann kann wahre Wunder wirken!\n\nUnd da er ja jetzt für uns arbeitet, könnten wir doch zu ihm gehen und seine Meinung einholen?", sourceObjective = "Sprecht mit Winstone Wolf.", completion = "Die Lage bessert sich langsam. Aber meiner Erfahrung nach gibt es zu jeder guten Nachricht auch eine schlechte.", sourceObjectiveStatus = "unverified-source-field" }
