quests[43053] = { id = 43053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar Collapse Scenario - Door 03" }
quests[43054] = { id = 43054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein umfangreicher Vorrat", description = "Ich habe unsere Vorräte jetzt mehrfach überprüft, aber so sehr ich auch versuche, alles schönzurechnen, wir kommen nicht aus.\n\nDer Mangel an Nahrung und Medikamenten wird unsere Kriegsbemühungen zunichte machen... so einfach ist das.\n\nWir brauchen dringendst Nahrung oder Verbandszeug. Wenn Ihr wisst, wie man dieser Dinge habhaft werden kann, bringt sie mir.", sourceObjective = "Gebt 100 würzige Rippchenbraten, Hochberglachse oder seidengewebte Verbände für Lao Shus Vorräte ab. Bei dieser Aufgabe könnten sich berufliche Kenntnisse in Erster Hilfe und Kochkunst als hilfreich erweisen.", completion = "Wunderbar, ja, ja! Diese Vorräte werden unser Lagerhaus für die nächsten Wochen füllen. Ich danke Euch von ganzem Herzen, Großmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[43055] = { id = 43055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[43056] = { id = 43056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[43057] = { id = 43057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[43058] = { id = 43058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Würziger Rippchenbraten", progress = "Würziger Rippchenbraten ist eine leichte Mahlzeit. Wer in der Kochkunst bewandert ist, kann sie zubereiten. Solltet Ihr diesen Beruf nicht erlernt haben, könnt Ihr die Dienste eines Kochs in Anspruch nehmen.", completion = "Ja, die sind wunderbar. Ich werde sie sofort salzen und pökeln!" }
quests[43059] = { id = 43059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Fjordun" }
quests[43060] = { id = 43060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochberglachs", progress = "Dieser köstliche Fisch lebt in den Seen des Hochbergs. Den Beruf des Angelns zu ergreifen kann ertragreich und dankbar sein. Wie man mir sagte, gibt es aber auch viele Angler, die gerne Handel treiben.", completion = "Welch wunderschöner Fang! Ich habe noch nie einen Fisch dieser Größe gesehen! Vielen Dank, Großmeister." }
quests[43061] = { id = 43061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidengewebte Verbände", progress = "Habt Ihr Verbände besorgen können?", completion = "Diese Verbände werden viele Leben retten. Danke." }
quests[43062] = { id = 43062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterführende Ausbildung", description = "Ihr mögt <der Großmeister/die Großmeisterin> sein, aber nur durch Disziplin erhält man die Meisterschaft aufrecht.\n\nUm perfekte Harmonie zu erreichen, müsst Ihr Eure Ausbildung fortsetzen.\n\nIch würde Eure Form gerne bei praktischen Übungen sehen, {name}. Geht und benutzt Eure Fähigkeiten 'Knisternder Jadeblitz', 'Rollen' und entweder 'Blackout-Tritt' oder 'Blackout-Schlag'. Die Disziplin führt uns zu wahrer Größe.", sourceObjective = "Verwendet Eure Fähigkeiten 'Knisternder Jadeblitz', 'Rollen' und entweder 'Blackout-Tritt' oder 'Blackout-Schlag' jeweils 10-mal.", progress = "Um Meisterschaft zu erreichen, müssen wir uns unermüdlich vervollkommnen.", completion = "Wirklich sehr beeindruckend, {name}. Ich hatte keinerlei Zweifel, dass Eure Form weiterhin spitzenmäßig ist.", sourceObjectiveStatus = "unverified-source-field" }
